public interface DatabaseDriverFactory {
    Connection createConnection();
    Statement createStatement();
}

public class PostgresFactory implements DatabaseDriverFactory {
    @Override
    public Connection createConnection() {
        return new PostgresConnection();
    }
    @Override
    public Statement createStatement() {
        return new PostgresStatement();
    }
}

public class Application {
    private final DatabaseDriverFactory factory;

    public Application(DatabaseDriverFactory factory) {
        this.factory = factory;
    }

    public void runQuery() {
        Connection conn = factory.createConnection();
        Statement stmt = factory.createStatement();
        stmt.execute("SELECT 1");
    }
}
